CREATE TABLE presupuesto (
	num_ot char(25),
	bus char(50),
	fecha_origen timestamp,
	status_ot char(3),
	fecha_cierre timestamp,
	area char(15),
	especialidad char(15),
	tipo_reporte char(15),
	trab_requerido char(600),
	cod_falla char(15),
	cod_accion char(15),
	cod_causa char(15),
	kms char(20),
	ot_trab_realizado char(600),
	cod_actividad char(25),
	act_tiporeporte char(15),
	act_trab_requerido char(600),
	num_rm float,
	codigo_item_srv char(25),
	desc_item_srv char(600),
	cant_usada float,
	udm char(8),
	costo_unitario float,
	subtotal float,
	fecha_uso timestamp,
	num_rt float,
	rt_area char(15),
	rt_especialidad char(15),
	rt_trab_requerido char(600),
	rt_trab_realizado char(600),
	planeador_mtlrs char(30),
	ubicacion char(30),
	ref_id float,
	especialidad_rec char(50));
